/**
 * The AI's judgement calls for the valuer ("Needs your eye", spec §5.3.6 and §5.4 item 8), generated by rules from the
 * data. Pure and deterministic: every flag, and every number in its texts, comes from the context, so client edits,
 * vacant units and valuer revisions recompute them consistently. Flag ids are stable across versions, so a review
 * status can be keyed by them.
 *
 * Rules:
 * - `cap_rate`: the market report gives no district-level cap rate.
 * - `market_rent`: the rent estimate is below high confidence, i.e. fewer than 10 listings, or more than 30 % of them
 *   older than 12 months. One failed criterion gives medium confidence, both give low.
 * - `under_rent`: the let units' total in-place rent differs from their market rent by more than 3 %. A gap above
 *   market is worded as an over-rent (same parameter, same id).
 * - `easement-<id>`: each section II entry of the land register.
 * - `missing_document-<type>`: each required document type without a readable document of that type.
 * - `extraction-<docId>-<field path>`: each field a document lists as uncertain.
 * - `manual_unit-<unitId>`: each unit added by hand, with its market rent.
 * - `vacancy-<unitId>`: each vacant unit; its swing is its share of the vacancy deduction.
 * - `land_value`: the land-value lookup has low confidence (no sample BORIS zone).
 *
 * Swings are the engine's sensitivities: `low` is the downside delta and `high` the upside one, each labelled with the
 * input at that end. Flags with a swing come first, the largest total swing |low| + |high| first; the others follow in
 * FlagKind order.
 */
import {
  DOCUMENT_TYPE_LABEL,
  type Confidence,
  type Deal,
  type DealDocument,
  type DocumentType,
  type Easement,
  type Feature,
  type FloorCode,
  type PropertyFacts,
  type Quote,
  type Unit,
} from "@/lib/deal/types";
import { eur, num, pct, rentM2, round2 } from "@/lib/format";
import type { LandValueLookup } from "@/lib/lookups/boris";
import { ANNEX3 } from "@/lib/lookups/costs";
import type { CapRateLookup, CapRateRow } from "@/lib/lookups/marketReport";
import type { BuildingRentSummary } from "@/lib/rent/estimator";
import type { UnitShare, ValuationParams, ValuationResult } from "@/lib/valuation/engine";
import type { Sensitivity } from "@/lib/valuation/sensitivity";

export type FlagKind =
  | "cap_rate"
  | "market_rent"
  | "under_rent"
  | "easement"
  | "missing_document"
  | "extraction"
  | "manual_unit"
  | "vacancy"
  | "land_value";

/** What the evidence pane shows for a flag. */
export type EvidenceRef =
  | { type: "market_report"; rowKey: CapRateRow["key"] }
  | { type: "comparables" }
  | { type: "document"; quote: Quote }
  | { type: "easement"; easementId: string }
  | { type: "land_value" }
  | { type: "none" };

export interface Flag {
  /** Stable across versions: the kind, plus the document type, document and field, easement or unit it concerns. */
  id: string;
  kind: FlagKind;
  title: string;
  confidence: Confidence;
  /** One line on what the AI did, shown under the title. */
  summary: string;
  whyFlagged: string;
  /** What would change the AI's mind; "" where the spec names nothing (the market rent, which has `support`). */
  changeMind: string;
  /** Evidence backing the call, e.g. a recent letting in the building for the market rent. */
  support: string | null;
  /**
   * Effect on the exact market value (€, unrounded) at the two ends of the call's plausible range: `low` is the
   * downside (the lower delta), `high` the upside. Each label names that end's input, e.g. "3.5 %" or "8 years".
   * null when the effect is not computed.
   */
  swing: { low: number; high: number; lowLabel: string; highLabel: string } | null;
  evidence: EvidenceRef;
  acceptLabel: string;
}

export interface FlagContext {
  deal: Deal;
  valuation: ValuationResult;
  rent: BuildingRentSummary;
  capRate: CapRateLookup;
  land: LandValueLookup;
  sensitivities: Sensitivity[];
  params: ValuationParams;
}

/** The documents a whole-building valuation needs (spec §5.3.2). */
export const REQUIRED_DOCS: DocumentType[] = [
  "tenant_list",
  "land_register",
  "energy_certificate",
  "refurbishment_sheet",
  "zoning_plan",
];

/**
 * Builds the flags for one version of a deal: flags with a swing first, by total swing |low| + |high| (largest first),
 * then the flags without a swing in FlagKind order; ties keep the order in which the rules raise them.
 *
 * Ranking by the whole swing rather than its larger end keeps the spec's order for the sample deal: the under-rent
 * (−11,235 / +8,063) comes before the easement (−12,480 / 0).
 */
export function buildFlags(ctx: FlagContext): Flag[] {
  return rank(
    uniqueById([
      ...capRateFlags(ctx),
      ...marketRentFlags(ctx),
      ...underRentFlags(ctx),
      ...easementFlags(ctx),
      ...missingDocumentFlags(ctx),
      ...extractionFlags(ctx),
      ...manualUnitFlags(ctx),
      ...vacancyFlags(ctx),
      ...landValueFlags(ctx),
    ]),
  );
}

// ---------------------------------------------------------------------------------------------------------------------
// Rule thresholds

const KIND_ORDER: FlagKind[] = [
  "cap_rate",
  "market_rent",
  "under_rent",
  "easement",
  "missing_document",
  "extraction",
  "manual_unit",
  "vacancy",
  "land_value",
];
/** The market-rent estimate is below high confidence with fewer listings than this … */
const MIN_LISTINGS = 10;
/** … or with a larger share of older listings than this. */
const MAX_OLDER_SHARE = 0.3;
/** The estimator index-adjusts listings older than this many months (spec §6.3). */
const OLDER_LISTING_MONTHS = 12;
/** The let units' total gap to market must exceed this share to raise the under-rent call. */
const MIN_RENT_GAP = 0.03;
/** A letting backs the market rent when it started at most this many years before the valuation year. */
const RECENT_LETTING_YEARS = 2;
/** Tolerance for comparing computed shares with the thresholds. */
const EPS = 1e-9;

// ---------------------------------------------------------------------------------------------------------------------
// The rules

const CAP_RATE_GROUP: Record<CapRateRow["key"], { short: string; sales: string }> = {
  efh: { short: "one- and two-family houses", sales: "one- and two-family houses" },
  mfh_pre1949: { short: "pre-war MFH", sales: "pre-war houses" },
  mfh_post1949: { short: "post-war MFH", sales: "post-war houses" },
  mixed: { short: "mixed-use buildings", sales: "mixed-use buildings" },
};

/** The AI takes the committee's city-wide median when the report has no district figure. */
function capRateFlags(ctx: FlagContext): Flag[] {
  const { row, districtValue } = ctx.capRate;
  if (districtValue !== null) return [];
  const zip = ctx.deal.address.zip.trim();
  const group = CAP_RATE_GROUP[row.key];
  const range = pctRange(row.range);
  const committee = `the valuation committee's city-wide range for ${row.label.toLowerCase()} (${range}, n = ${row.n})`;
  const rate = ctx.params.capRate;
  // The AI always proposes the median; any other rate in the parameters was set by the valuer.
  const proposedByAi = Math.abs(rate - row.median) < EPS;
  return [
    {
      id: "cap_rate",
      kind: "cap_rate",
      title: `Cap rate ${pct(rate)}`,
      confidence: "medium",
      summary: proposedByAi
        ? `Median of ${committee}.`
        : `Set by the valuer; the AI proposed ${pct(row.median)}, the median of ${committee}.`,
      whyFlagged: `The market report gives no district figure for ${zip || "this address"}, so the AI used the city-wide median of the ${range} range for ${group.short}.`,
      changeMind: `A district cap rate, or recent sales of ${group.sales} in ${zip || "the area"}.`,
      support: null,
      swing: swingOf(sensitivity(ctx, "capRate"), (r) => pct(r)),
      evidence: { type: "market_report", rowKey: row.key },
      acceptLabel: `Accept ${pct(rate)}`,
    },
  ];
}

function marketRentFlags(ctx: FlagContext): Flag[] {
  const { rent, valuation, params } = ctx;
  const listings = rent.recentCount + rent.olderCount;
  const few = listings < MIN_LISTINGS;
  const old = rent.olderShare > MAX_OLDER_SHARE + EPS;
  if ((!few && !old) || !(valuation.livingAreaM2 > 0) || valuation.units.length === 0) return [];

  // The market rent in use: the estimator's, or the valuer's factor and overrides applied to it.
  const average = valuation.grossIncome / 12 / valuation.livingAreaM2;
  const rents = valuation.units.map((u) => u.marketRentPerM2);
  const lowest = Math.min(...rents);
  const highest = Math.max(...rents);
  const unitsText =
    rents.length === 1
      ? `the unit is at ${rentM2(highest)}`
      : rentNumber(lowest) === rentNumber(highest)
        ? `all units are at ${rentM2(highest)}`
        : `units range from ${rentNumber(lowest)} to ${rentM2(highest)}`;
  const adjusted = params.marketRentFactor !== 1 || Object.keys(params.marketRentOverrides ?? {}).length > 0;

  const listingsText = count(listings, "comparable listing");
  const found = `only ${listingsText} ${listings === 1 ? "was" : "were"} found`;
  const olderText = `older than ${OLDER_LISTING_MONTHS} months`;
  const reason =
    few && old
      ? `${found}, ${rent.olderCount} of them ${olderText}`
      : few
        ? found
        : `${rent.olderCount} of the ${listings} listings ${rent.olderCount === 1 ? "is" : "are"} ${olderText}`;

  return [
    {
      id: "market_rent",
      kind: "market_rent",
      title: `Market rent ${rentM2(average)} (avg. of ${count(valuation.units.length, "unit")})`,
      confidence: few && old ? "low" : "medium",
      summary: `Estimated per unit from ${listingsText} (location base ${rentM2(rent.base)}); ${unitsText}.${adjusted ? " The valuer adjusted the market rent." : ""}`,
      whyFlagged: `These are asking rents, not leases, and ${reason}.`,
      // The spec names nothing that would change the AI's mind here ("—"); the support takes that place.
      changeMind: "",
      support: relettingSupport(ctx),
      swing: swingOf(sensitivity(ctx, "marketRent"), (r) => rentM2(r)),
      evidence: { type: "comparables" },
      acceptLabel: `Accept ${rentM2(average)}`,
    },
  ];
}

/**
 * The most recent letting of a unit from the tenant list, compared with the estimator, e.g. "Unit 4 was re-let in 2025
 * at 9.40 €/m² against an estimate of 9.64 €/m² (−2.5 %)." Units added by hand are no document evidence.
 */
function relettingSupport(ctx: FlagContext): string | null {
  const valuationYear = Number.parseInt(ctx.deal.valuationDate.slice(0, 4), 10);
  const lettings = ctx.deal.units
    .map((unit, index) => ({ unit, index }))
    .filter(
      ({ unit: u }) =>
        u.origin === "extracted" &&
        u.inPlaceRentPerM2 !== null &&
        u.leaseSinceYear !== null &&
        (!Number.isFinite(valuationYear) || u.leaseSinceYear >= valuationYear - RECENT_LETTING_YEARS),
    )
    // The latest letting first; on a tie the unit listed first.
    .sort((a, b) => (b.unit.leaseSinceYear ?? 0) - (a.unit.leaseSinceYear ?? 0) || a.index - b.index);
  for (const { unit } of lettings) {
    const estimate = ctx.rent.units.find((e) => e.unitId === unit.id)?.rentPerM2;
    const inPlace = unit.inPlaceRentPerM2;
    if (estimate === undefined || !(estimate > 0) || inPlace === null) continue;
    return `${unitRef(unit)} was re-let in ${unit.leaseSinceYear} at ${rentM2(inPlace)} against an estimate of ${rentM2(estimate)} (${signedPct(inPlace / estimate - 1)}).`;
  }
  return null;
}

/** How long the let units' gap to market lasts: an under-rent closing, or an over-rent ending. */
function underRentFlags(ctx: FlagContext): Flag[] {
  const { valuation, deal, params } = ctx;
  const areaById = new Map(deal.units.map((u) => [u.id, u.areaM2]));
  const letUnits = valuation.units.filter(
    (s): s is UnitShare & { inPlaceRentPerMonth: number } => s.inPlaceRentPerMonth !== null,
  );
  const inPlace = sum(letUnits.map((s) => s.inPlaceRentPerMonth));
  const market = sum(letUnits.map((s) => s.marketRentPerMonth));
  const letArea = sum(letUnits.map((s) => areaById.get(s.unitId) ?? 0));
  if (letUnits.length === 0 || !(market > 0) || !(letArea > 0)) return [];
  const gap = (inPlace - market) / market;
  if (!(Math.abs(gap) > MIN_RENT_GAP + EPS)) return [];

  const under = gap < 0;
  const gaps = letUnits.map((s) => s.gapPct).filter((g): g is number => g !== null);
  const affected = gaps.filter((g) => (under ? g < 0 : g > 0)).length;
  const who = payers(affected, letUnits.length, letUnits.length === valuation.units.length);
  // From the smallest gap to the largest one in the direction of the call.
  const [from, to] = under ? [Math.max(...gaps), Math.min(...gaps)] : [Math.min(...gaps), Math.max(...gaps)];
  const gapsText =
    gaps.length === 0
      ? ""
      : signedPct(from) === signedPct(to)
        ? `; unit gap ${signedPct(from)}`
        : `; unit gaps from ${signedPct(from)} to ${signedPct(to)}`;
  const rates = `${rentNumber(inPlace / letArea)} vs. ${rentM2(market / letArea)}${gapsText}`;
  const perYear = eur(Math.abs(valuation.underRentPerYear));
  const duration = years(params.underRentYears);
  const totalRow = deal.property.tenantListTotalSource;

  return [
    {
      id: "under_rent",
      kind: "under_rent",
      title: under ? `Under-rent closes within ${duration}` : `Over-rent lasts ${duration}`,
      confidence: "medium",
      summary: under
        ? `${who} below market (${rates}). The gap of ${perYear} a year is deducted until it closes.`
        : `${who} above market (${rates}). The surplus of ${perYear} a year is added until it ends.`,
      whyFlagged: under
        ? "Rent increases in sitting tenancies are capped (§ 558 BGB, local rent index)."
        : "In-place rents above market last only until the tenants move out.",
      changeMind: under
        ? "The dates of the last rent increase per unit."
        : "The remaining lease terms of the units let above market.",
      support: null,
      swing: swingOf(sensitivity(ctx, "underRentYears"), years),
      evidence: totalRow ? { type: "document", quote: { ...totalRow } } : { type: "none" },
      acceptLabel: `Accept ${duration}`,
    },
  ];
}

/** "All 8 units pay", "All 7 let units pay", "6 of 8 units pay", "1 of 8 units pays", "The unit pays". */
function payers(affected: number, letCount: number, allLet: boolean): string {
  if (affected === letCount) {
    if (letCount === 1) return allLet ? "The unit pays" : "The let unit pays";
    return `All ${letCount} ${allLet ? "units" : "let units"} pay`;
  }
  return `${affected} of ${letCount} ${allLet ? "units" : "let units"} ${affected === 1 ? "pays" : "pay"}`;
}

interface EasementWording {
  name: string;
  whyFlagged: string;
  changeMind: string;
}

const UTILITY_LINE = /leitung|kabel|utility|pipe|cable/i;
const RIGHT_OF_WAY = /wegerecht|gehrecht|fahrrecht|fahrtrecht|überfahrt|right of way/i;

/** The wording of an easement call by the kind of right, read from the entry and its translation. */
function easementWording(e: Easement): EasementWording {
  const text = `${e.text} ${e.translation}`;
  if (UTILITY_LINE.test(text)) {
    return {
      name: "Utility easement",
      whyFlagged: "The route of the utility line is not documented; the AI assumes it runs along the boundary.",
      changeMind: "A cadastral map showing the line crossing the buildable area.",
    };
  }
  if (RIGHT_OF_WAY.test(text)) {
    return {
      name: "Right of way",
      whyFlagged: "The route of the right of way is not documented; the AI assumes it runs along the boundary.",
      changeMind: "A cadastral map showing the way crossing the buildable area.",
    };
  }
  return {
    name: "Easement",
    whyFlagged: "What the easement covers is not documented; the AI assumes it does not restrict the use of the plot.",
    changeMind: "The registration approval (Eintragungsbewilligung) showing what the easement covers.",
  };
}

/** One call per section II entry. The easement deduction is one figure for the whole building. */
function easementFlags(ctx: FlagContext): Flag[] {
  const { easements } = ctx.deal.property;
  const deduction = ctx.params.easementDeduction;
  const deducted = deduction > 0;
  const swing = swingOf(sensitivity(ctx, "easement"), (input) => easementLabel(input, ctx.valuation.landValue));
  return easements.map((e): Flag => {
    const wording = easementWording(e);
    return {
      id: `easement-${e.id}`,
      kind: "easement",
      title: !deducted
        ? `${wording.name} assumed value-neutral`
        : easements.length === 1
          ? `${wording.name} deducted at ${eur(deduction)}`
          : `${wording.name}: part of the ${eur(deduction)} easement deduction`,
      confidence: "low",
      summary: `Land register, section II: ${sentence(e.translation || e.text)}`,
      whyFlagged: wording.whyFlagged,
      changeMind: wording.changeMind,
      support: null,
      swing: swing && { ...swing },
      evidence: { type: "easement", easementId: e.id },
      acceptLabel: deducted ? `Accept ${eur(-deduction)}` : "Accept ±€0",
    };
  });
}

/** "5 % of land value" at the maximum impact, "value-neutral" at none. */
function easementLabel(input: number, landValue: number): string {
  if (input === 0) return "value-neutral";
  return landValue > 0 ? `${shortPct(Math.abs(input) / landValue)} of land value` : eur(input);
}

/** Short English names of the document types, as used inside sentences. */
const DOCUMENT_NOUN: Record<DocumentType, string> = {
  tenant_list: "tenant list",
  land_register: "land register",
  condo_land_register: "condominium land register",
  energy_certificate: "energy certificate",
  refurbishment_sheet: "refurbishment sheet",
  zoning_plan: "zoning plan",
  unknown: "document",
};

/** A Wohnungsgrundbuch carries the land register's data, so it stands in for the land register. */
const COVERED_BY: Partial<Record<DocumentType, DocumentType[]>> = {
  land_register: ["land_register", "condo_land_register"],
};

interface MissingWording {
  confidence: Confidence;
  whyFlagged: string;
  changeMind: string;
}

const MISSING_WORDING: Partial<Record<DocumentType, MissingWording>> = {
  tenant_list: {
    confidence: "low",
    whyFlagged: "Without a tenant list, the units, areas and in-place rents rest on the client's entries alone.",
    changeMind: "The tenant list (Mieterliste) with area and rent per unit.",
  },
  land_register: {
    confidence: "low",
    whyFlagged: "Without a land register, the plot area and any easements in section II are unknown.",
    changeMind: "An extract from the land register (Grundbuch).",
  },
  energy_certificate: {
    confidence: "low",
    whyFlagged:
      "Without an energy certificate, the year of construction is unknown and the living area cannot be cross-checked.",
    changeMind: "The energy certificate (Energieausweis).",
  },
  refurbishment_sheet: {
    confidence: "low",
    whyFlagged:
      "Without a refurbishment sheet, no modernisation is credited, so the remaining economic life follows from the building's age.",
    changeMind: "A refurbishment sheet (Sanierungsübersicht) with the measures and their years.",
  },
  zoning_plan: {
    confidence: "medium",
    whyFlagged: "Without a zoning plan, the AI assumes the current residential use is permitted.",
    changeMind: "An excerpt from the zoning plan (B-Plan) for the plot.",
  },
};

/** A required type counts as present with a document of that type that did not fail to read. */
function missingDocumentFlags(ctx: FlagContext): Flag[] {
  const documents = ctx.deal.documents;
  const present = new Set(documents.filter((d) => d.status !== "failed").map((d) => d.type));
  return REQUIRED_DOCS.filter((type) => !(COVERED_BY[type] ?? [type]).some((t) => present.has(t))).map(
    (type): Flag => {
      const noun = DOCUMENT_NOUN[type];
      const wording = MISSING_WORDING[type] ?? {
        confidence: "low",
        whyFlagged: `Without ${withArticle(noun)}, its facts are unknown.`,
        changeMind: `The ${noun}.`,
      };
      return {
        id: `missing_document-${type}`,
        kind: "missing_document",
        title: `${DOCUMENT_TYPE_LABEL[type]} missing`,
        confidence: wording.confidence,
        summary:
          documents.length === 0
            ? "No documents were uploaded."
            : documents.length === 1
              ? `The uploaded document is not ${withArticle(noun)}.`
              : `None of the ${documents.length} uploaded documents is ${withArticle(noun)}.`,
        whyFlagged: wording.whyFlagged,
        changeMind: wording.changeMind,
        support: null,
        swing: null,
        evidence: { type: "none" },
        acceptLabel: `Accept without ${noun}`,
      };
    },
  );
}

function extractionFlags(ctx: FlagContext): Flag[] {
  return ctx.deal.documents.flatMap((doc) => doc.uncertainFields.map((path) => extractionFlag(ctx.deal, doc, path)));
}

function extractionFlag(deal: Deal, doc: DealDocument, path: string): Flag {
  const noun = DOCUMENT_NOUN[doc.type];
  const located = fieldQuote(deal, doc, path);
  const onPage = located ? `, p. ${located.quote.page}` : "";
  const common: Omit<Flag, "summary" | "whyFlagged" | "changeMind"> = {
    id: `extraction-${doc.id}-${path}`,
    kind: "extraction",
    title: `AI unsure: ${fieldLabel(deal, doc, path)} in the ${noun}`,
    confidence: "low",
    support: null,
    swing: null,
    evidence: located ? { type: "document", quote: { ...located.quote } } : { type: "none" },
    acceptLabel: "Confirm reading",
  };

  const unreadable = unreadableRentUnit(deal, doc, path);
  if (unreadable) {
    const name = unitName(unreadable);
    return {
      ...common,
      summary: `No rent could be read for ${name}.`,
      whyFlagged: `The ${noun} shows ${name} as let, but the AI could not read its rent, so the unit is valued as vacant.`,
      changeMind: "The unit's rent per month from the tenant list or the lease.",
    };
  }

  // Only the field's own citation tells whether its quote was found and how sure the AI was.
  const own = located?.exact ? located.quote : null;
  return {
    ...common,
    summary: own ? `Read from p. ${own.page}: “${own.quote}”.` : `Read from the ${noun}${onPage}.`,
    whyFlagged:
      own && !own.verified
        ? `The quote was not found on p. ${own.page} of the ${noun}, so the value could not be traced.`
        : own && own.confidence === "low"
          ? "The AI read this value with low confidence."
          : "The AI marked this value as uncertain, or its quote was not found on the stated page.",
    changeMind: `Confirmation that the value matches the ${noun}${onPage}.`,
  };
}

const UNIT_ROW = /^tenantList\.units\.(\d+)\.(\w+)$/;
const MEASURE_ROW = /^refurbishmentSheet\.measures\.(\d+)\.(\w+)$/;
const EASEMENT_ROW = /^landRegister\.easements\.(\d+)\.text$/;

const UNIT_FIELD_LABEL: Record<string, string> = {
  label: "name",
  floor: "floor",
  areaM2: "area",
  rooms: "rooms",
  rentPerMonth: "rent",
  leaseSinceYear: "lease start",
};

const FIELD_LABEL: Record<string, string> = {
  "tenantList.totalAreaM2": "total living area",
  "tenantList.totalRentPerMonth": "rent total",
  "tenantList.address": "address",
  "landRegister.parcel": "parcel",
  "landRegister.plotM2": "plot area",
  "landRegister.address": "address",
  "energyCertificate.address": "address",
  "energyCertificate.builtYear": "year of construction",
  "energyCertificate.heatingYear": "heating year",
  "energyCertificate.energyCarrier": "energy carrier",
  "energyCertificate.energyClass": "energy class",
  "energyCertificate.demandKwh": "energy demand",
  "energyCertificate.livingAreaM2": "living area",
  "zoningPlan.areaType": "area type",
  "zoningPlan.residentialAllowed": "residential use",
};

/** The tenant-list row `i` is unit `u{i+1}` (see dealFromExtractions), if the deal took its units from this document. */
function unitOfRow(deal: Deal, doc: DealDocument, row: string): Unit | null {
  const unit = deal.units.find((u) => u.id === `u${Number(row) + 1}`);
  return unit && unit.source?.documentId === doc.id ? unit : null;
}

/** "plot area", "area of GF left", "measure “Roof incl. insulation”", "section II entry 1". */
function fieldLabel(deal: Deal, doc: DealDocument, path: string): string {
  const unitRow = UNIT_ROW.exec(path);
  if (unitRow) {
    const unit = unitOfRow(deal, doc, unitRow[1]);
    const field = UNIT_FIELD_LABEL[unitRow[2]] ?? unitRow[2];
    return `${field} of ${unit ? unitName(unit) : `unit ${Number(unitRow[1]) + 1}`}`;
  }
  const measureRow = MEASURE_ROW.exec(path);
  if (measureRow) {
    const measure = deal.property.refurbishments[Number(measureRow[1])];
    const name = measure && measure.source.documentId === doc.id ? `“${measure.name}”` : `${Number(measureRow[1]) + 1}`;
    return measureRow[2] === "year" ? `year of measure ${name}` : `measure ${name}`;
  }
  const easementRow = EASEMENT_ROW.exec(path);
  if (easementRow) return `section II entry ${Number(easementRow[1]) + 1}`;
  return FIELD_LABEL[path] ?? path;
}

/** Fields whose own citation (`exact`) or the citation next to them the deal keeps. */
const KEPT_QUOTES: Record<string, { quote: (p: PropertyFacts) => Quote | null | undefined; exact: boolean }> = {
  "tenantList.totalRentPerMonth": { quote: (p) => p.tenantListTotalSource, exact: true },
  "tenantList.totalAreaM2": { quote: (p) => p.tenantListTotalSource, exact: false },
  "landRegister.plotM2": { quote: (p) => p.plotSource, exact: true },
  "energyCertificate.builtYear": { quote: (p) => p.builtYearSource, exact: true },
  "zoningPlan.areaType": { quote: (p) => p.zoning?.source, exact: true },
  "zoningPlan.residentialAllowed": { quote: (p) => p.zoning?.source, exact: false },
};

/**
 * The quote that locates a field in its document: the field's own citation where the deal keeps it (`exact`), else
 * the citation of its row (a unit's label, a measure's name, the rent total row). null when the deal keeps neither.
 */
function fieldQuote(deal: Deal, doc: DealDocument, path: string): { quote: Quote; exact: boolean } | null {
  let quote: Quote | null | undefined = null;
  let exact = false;
  const unitRow = UNIT_ROW.exec(path);
  const measureRow = MEASURE_ROW.exec(path);
  const easementRow = EASEMENT_ROW.exec(path);
  if (unitRow) {
    quote = unitOfRow(deal, doc, unitRow[1])?.source;
    exact = unitRow[2] === "label";
  } else if (measureRow) {
    quote = deal.property.refurbishments[Number(measureRow[1])]?.source;
    exact = measureRow[2] === "name";
  } else if (easementRow) {
    quote = deal.property.easements[Number(easementRow[1])]?.source;
    exact = true;
  } else if (KEPT_QUOTES[path]) {
    quote = KEPT_QUOTES[path].quote(deal.property);
    exact = KEPT_QUOTES[path].exact;
  }
  return quote && quote.documentId === doc.id ? { quote, exact } : null;
}

/** The unit behind `tenantList.units.<i>.rentPerMonth` when it was listed as let but no rent could be read. */
function unreadableRentUnit(deal: Deal, doc: DealDocument, path: string): Unit | null {
  const unitRow = UNIT_ROW.exec(path);
  if (!unitRow || unitRow[2] !== "rentPerMonth") return null;
  const unit = unitOfRow(deal, doc, unitRow[1]);
  return unit && unit.inPlaceRentPerM2 === null ? unit : null;
}

const FLOOR_NAME: Record<FloorCode, string> = {
  GF: "ground floor",
  "1F": "1st floor",
  "2F": "2nd floor",
  "3F": "3rd floor",
  "4F": "4th floor",
  attic: "attic",
};

const FEATURE_NAME: Record<Feature, string> = {
  balcony: "balcony",
  roof_terrace: "roof terrace",
  renovated_bath: "renovated bathroom",
  street: "street side",
  courtyard: "courtyard side",
};

/** A unit added by hand has no document behind it; the call shows its estimated market rent. */
function manualUnitFlags(ctx: FlagContext): Flag[] {
  return ctx.deal.units
    .filter((u) => u.origin === "manual")
    .map((u): Flag => {
      const estimate = ctx.rent.units.find((e) => e.unitId === u.id);
      const marketRent = ctx.valuation.units.find((s) => s.unitId === u.id)?.marketRentPerM2 ?? estimate?.rentPerM2;
      const name = unitName(u);
      const facts = [`${m2(u.areaM2)} m²`, FLOOR_NAME[u.floor], ...Array.from(new Set(u.features), (f) => FEATURE_NAME[f])];
      const basis = estimate
        ? `market rent estimated from ${count(estimate.comparableIds.length, "comparable listing")} of similar size (${estimate.confidence} confidence)`
        : "no market rent estimate";
      return {
        id: `manual_unit-${u.id}`,
        kind: "manual_unit",
        title: marketRent === undefined ? `${name} added by hand` : `${name} added by hand, market rent ${rentM2(marketRent)}`,
        confidence: "low",
        summary: `${facts.join(", ")}; ${basis}.`,
        whyFlagged: `${name} was added by hand and is not in the tenant list, so no document confirms it.`,
        changeMind: "A tenant list or lease that includes the unit.",
        support: null,
        swing: null,
        evidence: { type: "comparables" },
        acceptLabel: marketRent === undefined ? "Accept unit" : `Accept ${rentM2(marketRent)}`,
      };
    });
}

/** Each vacant unit, with its share of the engine's vacancy deduction (months of market rent) as the downside. */
function vacancyFlags(ctx: FlagContext): Flag[] {
  const { valuation } = ctx;
  const shares = new Map(valuation.units.map((s) => [s.unitId, s]));
  const vacantMarketPerMonth = sum(
    valuation.units.filter((s) => s.inPlaceRentPerMonth === null).map((s) => s.marketRentPerMonth),
  );
  // The engine deducts the same number of months' market rent for every vacant unit.
  const monthsVacant =
    vacantMarketPerMonth > 0 ? valuation.vacancyDeduction / vacantMarketPerMonth : ANNEX3.vacancyMonths;
  const period = months(monthsVacant);

  return ctx.deal.units
    .filter((u) => u.inPlaceRentPerM2 === null)
    .map((u): Flag => {
      const share = shares.get(u.id);
      const name = unitName(u);
      const deduction = share ? share.marketRentPerMonth * monthsVacant : null;
      return {
        id: `vacancy-${u.id}`,
        kind: "vacancy",
        title: `${name} vacant: re-let within ${period}`,
        confidence: "medium",
        summary:
          share && deduction !== null
            ? `Valued at the market rent of ${rentM2(share.marketRentPerM2)} (${eur(share.marketRentPerMonth, { decimals: 2 })} a month), less ${monthsRent(monthsVacant)} for re-letting: ${eur(-deduction)}.`
            : `Valued at market rent, less ${monthsRent(monthsVacant)} for re-letting.`,
        whyFlagged: `${name} is vacant, so the AI assumes it is re-let at market rent after ${period}.`,
        changeMind: "A signed lease, or a letting agent's estimate of the time to re-let.",
        support: null,
        swing:
          deduction === null
            ? null
            : { low: deduction > 0 ? -deduction : 0, high: 0, lowLabel: period, highLabel: months(0) },
        evidence: u.source ? { type: "document", quote: { ...u.source } } : { type: "comparables" },
        acceptLabel: `Accept ${period}`,
      };
    });
}

/** Low confidence means the sample BORIS table has no zone for the address and a fallback value was used. */
function landValueFlags(ctx: FlagContext): Flag[] {
  const { land, deal, valuation } = ctx;
  if (land.confidence !== "low") return [];
  const value = `${num(land.valuePerM2)} €/m²`;
  const zip = deal.address.zip.trim();
  const plot = deal.property.plotM2;
  const applied = plot !== null && plot > 0 ? ` to the ${m2(plot)} m² plot (${eur(valuation.landValue)})` : "";
  return [
    {
      id: "land_value",
      kind: "land_value",
      title: `Land value ${value} assumed`,
      confidence: land.confidence,
      summary: `${land.note ?? "No standard land value for this address"}: the AI applied a fallback of ${value}${applied}.`,
      whyFlagged: `The sample BORIS table has no standard land value (Bodenrichtwert) for ${zip || "this address"}, so the AI used a fallback value.`,
      changeMind: "The standard land value (Bodenrichtwert) for the address, from BORIS.",
      support: null,
      swing: null,
      evidence: { type: "land_value" },
      acceptLabel: `Accept ${value}`,
    },
  ];
}

// ---------------------------------------------------------------------------------------------------------------------
// Swings and ranking

type Swing = NonNullable<Flag["swing"]>;

function sensitivity(ctx: FlagContext, key: Sensitivity["key"]): Sensitivity | null {
  return ctx.sensitivities.find((s) => s.key === key) ?? null;
}

/** Sorts a sensitivity's two ends into downside (`low`) and upside (`high`), each labelled with its input. */
function swingOf(s: Sensitivity | null, label: (input: number) => string): Swing | null {
  if (!s) return null;
  const [down, up] = s.high.delta < s.low.delta ? [s.high, s.low] : [s.low, s.high];
  // `+ 0` turns a −0 into 0.
  return { low: down.delta + 0, high: up.delta + 0, lowLabel: label(down.input), highLabel: label(up.input) };
}

function swingSize(s: Swing): number {
  return Math.abs(s.low) + Math.abs(s.high);
}

function rank(flags: Flag[]): Flag[] {
  return flags
    .map((flag, index) => ({ flag, index }))
    .sort((a, b) => {
      const sa = a.flag.swing;
      const sb = b.flag.swing;
      if (sa && sb) {
        const bySize = swingSize(sb) - swingSize(sa);
        if (Number.isFinite(bySize) && bySize !== 0) return bySize;
      } else if (sa || sb) {
        return sa ? -1 : 1;
      }
      return KIND_ORDER.indexOf(a.flag.kind) - KIND_ORDER.indexOf(b.flag.kind) || a.index - b.index;
    })
    .map(({ flag }) => flag);
}

/** Keeps the first flag of each id, so a duplicate input (e.g. a field listed twice) cannot duplicate a flag. */
function uniqueById(flags: Flag[]): Flag[] {
  const seen = new Set<string>();
  return flags.filter((f) => {
    if (seen.has(f.id)) return false;
    seen.add(f.id);
    return true;
  });
}

// ---------------------------------------------------------------------------------------------------------------------
// Text helpers

const MINUS = "−";

function sum(values: number[]): number {
  return values.reduce((acc, v) => acc + v, 0);
}

/** "1 unit", "8 units". */
function count(n: number, noun: string): string {
  return `${n} ${noun}${n === 1 ? "" : "s"}`;
}

function years(n: number): string {
  return count(n, "year");
}

/** "6 months", to one decimal at most. */
function months(n: number): string {
  return count(Math.round(n * 10) / 10, "month");
}

/** "6 months' rent", "1 month's rent". */
function monthsRent(n: number): string {
  const tenth = Math.round(n * 10) / 10;
  return tenth === 1 ? "1 month's rent" : `${tenth} months' rent`;
}

/** `+1.4 %`, `−2.5 %`, `0.0 %`. */
function signedPct(share: number): string {
  const text = pct(Math.abs(share));
  if (text === pct(0)) return text;
  return `${share < 0 ? MINUS : "+"}${text}`;
}

/** `2.5–3.5 %` for [0.025, 0.035]. */
function pctRange([low, high]: [number, number]): string {
  return `${(low * 100).toFixed(1)}–${pct(high)}`;
}

/** `5 %` or `2.5 %`: a share with at most one decimal. */
function shortPct(share: number): string {
  const tenth = Math.round(share * 1000) / 10;
  return `${Number.isInteger(tenth) ? tenth : tenth.toFixed(1)} %`;
}

/** `9.60`: a rent per m² without its unit, for ranges such as "9.17 to 9.92 €/m²". */
function rentNumber(x: number): string {
  return round2(x).toFixed(2);
}

/** `565` or `565.5`: areas to one decimal, without a trailing `.0`. */
function m2(area: number): string {
  const tenth = Math.round(area * 10) / 10;
  return num(tenth, Number.isInteger(tenth) ? 0 : 1);
}

function withArticle(noun: string): string {
  return `${/^[aeiou]/i.test(noun) ? "an" : "a"} ${noun}`;
}

/** The text with a closing full stop. */
function sentence(text: string): string {
  const t = text.trim();
  return /[.!?]$/.test(t) ? t : `${t}.`;
}

/** The unit's label, or "Unit <id>" for a unit without one. */
function unitName(u: Unit): string {
  return u.label.trim() || `Unit ${u.id}`;
}

/** "Unit 4" for the tenant list's 4th row (`u4`), else the unit's name. */
function unitRef(u: Unit): string {
  const row = /^u(\d+)$/.exec(u.id);
  return row ? `Unit ${row[1]}` : unitName(u);
}
